mod solution;

fn main() {
    let cases = [
    (r#"matrix=[[0,10,15,20],[10,0,35,25],[15,35,0,30],[20,25,30,0]]"#, r#"80"#),
    (r#"matrix=[[0,1,10],[1,0,2],[10,2,0]]"#, r#"13"#),
    (r#"
matrix=[[0,1,10],[1,0,2],[10,2,0]]
"#, r#"13"#),
    (r#"  
matrix=[[0,10,15,20],[10,0,35,25],[15,35,0,30],[20,25,30,0]]
  "#, r#"80"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS bitmask-dp");
}
